PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?film ?director ?deathDate WHERE {
  VALUES ?film { dbr:Empire_M dbr:The_Westland_Case }

  # director (prefer dbp, fallback to dbo)
  OPTIONAL { ?film dbp:director ?director . }
  OPTIONAL { ?film dbo:director ?director . }
  FILTER (BOUND(?director))

  # death date of the director (prefer dbp, fallback to dbo)
  OPTIONAL { ?director dbp:deathDate ?dbpDeath . }
  OPTIONAL { ?director dbo:deathDate ?dboDeath . }
  BIND (COALESCE(?dbpDeath, ?dboDeath) AS ?deathDate)
}
LIMIT 100

